Chapter: Nine days

The paragraph: In June the share price fell from 104.5 euros to 1.28 euros. Nobody could stop it.

This graphic covers: The share price fell from 104.5 euros to 1.28 euros.
Length: 5.0 s

Words spoken in it, from its start:
0.3 s  Acme
0.8 s  was
1.3 s  the
1.8 s  name
2.3 s  on
2.8 s  every
3.3 s  door.

Intent: Acme was the name on every door.
Rests on claims: 4

A passing design of this technique (logo-reveal: a lockup behind a pair of doors that slide apart as the name is said, its tracking settling, the line beneath), in this sandbox and on the tokens, to pattern on. Its words and figures are its own; yours come from this slot and its claims:
````jsx
// Concept: the name behind the doors. The line says the name was on every door, so the
// lockup sits behind a pair of doors: the frame of a doorway draws first, and as the name is
// said the two panels slide apart to show it; the name's tracking then settles while the
// rest of the line builds beneath. The concept comes from this line: a different line needs
// its own reveal.
// Storyboard, on the narration's clock:
//   0.0 s  the hook: the doorway's frame draws round, its two closed panels inside it
//   0.3 s  "Acme": the panels slide apart, blurred by their speed, and the lockup (the mark
//          when the producer holds it, the name beneath) is behind them, its tracking wide
//   0.85 s the panels are gone; the name's tracking settles over motion.ms.move
//   0.8 s to 3.3 s  "was the name on every door.": the line builds beneath, word by word
//   to the end: the lockup holds while the camera keeps a slow push
// The mark is drawn only when props.logos holds it; the name always shows, so a missing mark still reads.
// The mark fits a box of its own in both directions, so a square or tall mark fits as a wide one does,
// and the name is sized from its length, so "Deutsche Bank" fits the 9:16 frame as "Acme" does.
const NAME = 'Acme'

// Where the narration says the name: the index of the word that starts it, or -1.
function nameIndex(words) {
  return words.findIndex((word) => word.text.indexOf(NAME.split(' ')[0]) === 0)
}

// Helpers, called directly: 0 to 1 over lengthMs from atMs, held at 1, one per curve,
// since each interpolate names its curve in the call.
function range(fps, atMs, lengthMs) {
  return [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)]
}
function arrive(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.enter, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function travel(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}

// Motion blur that follows speed: a move of more than a few pixels a frame softens, and
// only while it is moving. moved is how far the element travelled since the last frame.
function blurFor(moved, unit) {
  const px = Math.min(8, Math.abs(moved) / (6 * unit)) * unit
  return px > 0.4 * unit ? 'blur(' + px.toFixed(2) + 'px)' : 'none'
}

// A helper, called directly: one door panel, sliding out to its side as it opens.
function panel(side, open, openBefore, spec) {
  const travelled = (side === 'left' ? -1 : 1) * spec.doorW * 0.5 * open
  const moved = spec.doorW * 0.5 * (open - openBefore)
  return (
    <div
      key={side}
      style={{
        position: 'absolute', top: 0, bottom: 0, width: '50%', left: side === 'left' ? 0 : '50%',
        backgroundColor: spec.colors.surface, transform: 'translateX(' + travelled + 'px)',
        borderRight: side === 'left' ? 2 * spec.unit + 'px solid ' + Remotion.withAlpha(spec.colors.textSecondary, 0.35) : 'none',
        borderLeft: side === 'right' ? 2 * spec.unit + 'px solid ' + Remotion.withAlpha(spec.colors.textSecondary, 0.35) : 'none',
        filter: blurFor(moved, spec.unit),
      }}
    />
  )
}

function Graphic(props) {
  const frame = Remotion.useCurrentFrame()
  const { width, height, fps } = Remotion.useVideoConfig()
  const { colors, fonts } = props.brand
  const inset = props.safeArea
  const portrait = height > width
  const unit = Math.min(width, height) / 1080

  const mark = props.logos ? props.logos[NAME] : undefined
  const roomW = width - inset.left - inset.right
  const roomH = height - inset.top - inset.bottom
  // The mark's box: at most this wide and this tall; the mark keeps its aspect ratio inside it.
  const maxW = Math.min(roomW, (portrait ? 720 : 680) * unit)
  const maxH = (portrait ? 0.26 : 0.3) * roomH
  const fit = mark ? Math.min(maxW / mark.width, maxH / mark.height) : 0
  const markWidth = mark ? mark.width * fit : 0
  const markHeight = mark ? mark.height * fit : 0
  // The name on one line: about 0.62 em a character plus the widest tracking, within the room.
  const nameSize = Math.min((mark ? 110 : 190) * unit, (0.8 * roomW) / (NAME.length * (0.62 + 0.14)))
  const gap = mark ? 36 * unit : 0
  const lockupH = markHeight + gap + nameSize * 1.1
  const doorW = Math.min(roomW, Math.max(markWidth, NAME.length * 0.76 * nameSize) + 160 * unit)
  const doorH = lockupH + 140 * unit

  const said = nameIndex(props.words)
  const nameAt = said >= 0 ? props.words[said].atMs : 300
  // The frame draws round first; the panels open on the name over motion.ms.reveal.
  const framed = arrive(frame, fps, 0, motion.ms.draw)
  const open = arrive(frame, fps, nameAt, motion.ms.reveal)
  const openBefore = arrive(frame - 1, fps, nameAt, motion.ms.reveal)
  const tracking = Remotion.interpolate(frame, range(fps, nameAt + motion.ms.reveal, motion.ms.move), [0.14, 0.04], {
    easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
  const push = travel(frame, fps, 0, props.durationMs)
  // The line beneath is what is said after the name, all of its words ("Deutsche Bank" is two).
  const line = said >= 0 ? props.words.slice(said + NAME.split(' ').length) : props.words.filter((word) => word.atMs > nameAt)
  const spec = { colors, unit, doorW }

  return (
    <Remotion.AbsoluteFill
      style={{
        paddingTop: inset.top, paddingRight: inset.right,
        paddingBottom: inset.bottom, paddingLeft: inset.left,
        justifyContent: 'center', alignItems: 'center', gap: 52 * unit,
        transform: 'scale(' + (1 + 0.03 * push) + ')',
      }}
    >
      <div style={{ position: 'relative', width: doorW, height: doorH, clipPath: 'inset(0)' }}>
        <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap }}>
          {mark ? <Remotion.Img src={mark.src} style={{ width: markWidth, height: markHeight }} /> : null}
          <div style={{ fontFamily: fonts.heading, fontSize: nameSize, lineHeight: 1.1, letterSpacing: tracking + 'em', color: colors.textPrimary, whiteSpace: 'nowrap' }}>
            {NAME}
          </div>
        </div>
        {open < 1 ? [panel('left', open, openBefore, spec), panel('right', open, openBefore, spec)] : null}
        <svg width={doorW} height={doorH} style={{ position: 'absolute', left: 0, top: 0 }}>
          <rect
            x={2 * unit} y={2 * unit} width={doorW - 4 * unit} height={doorH - 4 * unit} fill="none"
            stroke={colors.accent} strokeWidth={4 * unit} pathLength={1} strokeDasharray="1" strokeDashoffset={1 - framed}
          />
        </svg>
      </div>
      <div style={{ fontFamily: fonts.title, fontSize: 52 * unit, color: colors.textSecondary, textAlign: 'center' }}>
        {line.map((word) => {
          const enter = arrive(frame, fps, word.atMs, motion.ms.enter)
          return (
            <span key={word.atMs} style={{ display: 'inline-block', marginRight: '0.25em', opacity: enter, transform: 'translateY(' + (1 - enter) * motion.px.rise * unit + 'px)' }}>
              {word.text}
            </span>
          )
        })}
      </div>
    </Remotion.AbsoluteFill>
  )
}

````
